mapper.update:
        UPDATE ALERT
		SET ALERT_CHK = 2
		WHERE ALERT_NO = #{alertNo}
		AND USER_NO = #{userNo}

mapper.select:
        SELECT ALERT_NO, ALERT_CN, ALERT_CHK, ALERT_CREATE, ALERT_TY
				, USER_NO, ALERT_PK, ALERT_URL, ALERT_FILE
        FROM ALERT
        WHERE ALERT_NO = #{alertNo} 
        AND USER_NO = #{userNo}

    	SELECT SUGGEST_BOARD_NO, SUGGEST_CONTENT, SUGGEST_DATE, USER_NO, SUGGEST_TITLE, SUGGEST_STATUS
		FROM SUGGEST_BOARD
		WHERE SUGGEST_BOARD_NO = #{suggestBoardNo}

    	SELECT REP_NO, PARENT_NO, SUGGEST_BOARD_NO, REP_USER
		FROM REPLY
		WHERE REP_NO = #{repNo}
